DO $$ BEGIN IF EXISTS(SELECT 1 FROM institutional_program_cases WHERE created_by_user_id IS NOT NULL) OR EXISTS(SELECT 1 FROM health_alerts WHERE created_by_user_id IS NOT NULL) OR EXISTS(SELECT 1 FROM complaints WHERE created_by_user_id IS NOT NULL OR decision_reason IS NOT NULL OR referral_destination IS NOT NULL) THEN RAISE EXCEPTION '0022 down would discard API data'; END IF; END $$;
DROP TRIGGER IF EXISTS complaints_version ON complaints; DROP TRIGGER IF EXISTS health_alerts_version ON health_alerts; DROP TRIGGER IF EXISTS institutional_program_cases_version ON institutional_program_cases;
DROP TRIGGER IF EXISTS complaints_case_sync ON complaints; DROP TRIGGER IF EXISTS health_alerts_case_sync ON health_alerts;
CREATE OR REPLACE FUNCTION sync_case_from_health_alert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.decision='PROCEEDS' THEN UPDATE cases SET status='PENDING_ASSIGNMENT' WHERE id=NEW.case_id AND status='PENDING_REVIEW'; ELSIF NEW.decision='NOT_PROCEEDS' THEN UPDATE cases SET status='NO_ACTION',closed_at=clock_timestamp(),closed_reason=COALESCE(NULLIF(btrim(NEW.decision_reason),''),'Alerta no procede') WHERE id=NEW.case_id AND status='PENDING_REVIEW'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION sync_case_from_complaint() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.decision='PROCEEDS' THEN UPDATE cases SET status='PENDING_ASSIGNMENT' WHERE id=NEW.case_id AND status='PENDING_REVIEW'; ELSIF NEW.decision='NOT_PROCEEDS' THEN UPDATE cases SET status='NO_ACTION',closed_at=clock_timestamp(),closed_reason='Denuncia no procede' WHERE id=NEW.case_id AND status='PENDING_REVIEW'; ELSIF NEW.decision='REFERRED' THEN UPDATE cases SET status='REFERRED',closed_at=clock_timestamp(),closed_reason=NEW.referral_reason WHERE id=NEW.case_id AND status='PENDING_REVIEW'; END IF; RETURN NEW; END $$;
CREATE TRIGGER health_alerts_case_sync AFTER INSERT OR UPDATE ON health_alerts FOR EACH ROW EXECUTE FUNCTION sync_case_from_health_alert();
CREATE TRIGGER complaints_case_sync AFTER INSERT OR UPDATE ON complaints FOR EACH ROW EXECUTE FUNCTION sync_case_from_complaint();
DROP TRIGGER IF EXISTS complaints_guard ON complaints; DROP TRIGGER IF EXISTS health_alerts_guard ON health_alerts; DROP TRIGGER IF EXISTS institutional_program_cases_guard ON institutional_program_cases; DROP FUNCTION IF EXISTS intake_source_guard();
DROP TRIGGER IF EXISTS cases_intake_organization_guard ON cases; DROP FUNCTION IF EXISTS intake_case_organization_guard();
DROP INDEX IF EXISTS health_alerts_number_normalized_unique;
ALTER TABLE health_alerts DROP CONSTRAINT IF EXISTS health_alerts_alert_number_not_blank;
ALTER TABLE complaints DROP CONSTRAINT IF EXISTS complaints_complainant_data_allowlist; DROP FUNCTION IF EXISTS complaint_data_is_valid(jsonb);
ALTER TABLE complaints DROP CONSTRAINT IF EXISTS complaints_decision_coherent; ALTER TABLE complaints ADD CONSTRAINT complaints_check1 CHECK((decision='PENDING' AND decided_at IS NULL AND decided_by_user_id IS NULL) OR (decision IN('PROCEEDS','NOT_PROCEEDS') AND decided_at IS NOT NULL AND decided_by_user_id IS NOT NULL AND referral_reason IS NULL) OR (decision='REFERRED' AND decided_at IS NOT NULL AND decided_by_user_id IS NOT NULL AND referral_reason IS NOT NULL AND btrim(referral_reason)<>''));
ALTER TABLE health_alerts DROP CONSTRAINT IF EXISTS health_alerts_decision_coherent; ALTER TABLE health_alerts ADD CONSTRAINT health_alerts_check1 CHECK((decision='PENDING' AND decided_at IS NULL AND decided_by_user_id IS NULL) OR (decision IN('PROCEEDS','NOT_PROCEEDS') AND decided_at IS NOT NULL AND decided_by_user_id IS NOT NULL));
ALTER TABLE complaints DROP COLUMN updated_at,DROP COLUMN created_at,DROP COLUMN version,DROP COLUMN referral_destination,DROP COLUMN decision_reason,DROP COLUMN created_by_user_id;
ALTER TABLE health_alerts DROP COLUMN updated_at,DROP COLUMN created_at,DROP COLUMN version,DROP COLUMN created_by_user_id;
ALTER TABLE institutional_program_cases DROP COLUMN updated_at,DROP COLUMN created_at,DROP COLUMN version,DROP COLUMN created_by_user_id;
